/* ---------- captions (burned in, word for word; max 2 lines, bottom edge at y=1340) ---------- */

// [scene, firstWord, lastWord] per caption chunk; chunks cover every narrated word once, in order.
export const CHUNKS: [number, number, number][] = [
  [0, 0, 2],
  [1, 0, 4],
  [1, 5, 12],
  [2, 0, 3],
  [2, 4, 10],
  [3, 0, 5],
  [3, 6, 12],
  [4, 0, 4],
  [4, 5, 7],
  [5, 0, 5],
];
const TOKENS = LINES.map((s) => s.text.split(' '));

const Captions: React.FC = () => {
  const f = useCurrentFrame();
  let idx = -1;
  CHUNKS.forEach(([s, a], i) => {
    if (f >= wordF(s, a) - 1) idx = i;
  });
  if (idx < 0) return null;
  const [s, a, b] = CHUNKS[idx];
  const first = wordF(s, a);
  const t = interpolate(f, [first - 1, first + 4], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  return (
    <Layer kind="cap">
      <div style={{position: 'absolute', left: COL_L, width: COL_W, bottom: 1920 - 1340, display: 'flex', justifyContent: 'center', fontFamily: FONT, transform: `translateY(${(1 - t) * 14}px)`, opacity: t}}>
        <div style={{maxWidth: COL_W, boxSizing: 'border-box', padding: '14px 30px', borderRadius: 36, background: WHITE, border: '3px solid #9FBFEA', boxShadow: '0 4px 10px rgba(26,80,160,0.12)', fontSize: 48, lineHeight: 1.22, fontWeight: 800, textAlign: 'center'}}>
          {TOKENS[s].slice(a, b + 1).map((tok, i) => {
            const wi = a + i;
            const started = f >= wordF(s, wi);
            const nextStart = wi + 1 < LINES[s].words.length ? wordF(s, wi + 1) : Infinity;
            const active = started && f < nextStart;
            return (
              <React.Fragment key={wi}>
                <span style={{color: started ? INK : MUTED, background: active ? ORANGE : 'transparent', borderRadius: 12, padding: '0 4px', margin: '0 -4px', whiteSpace: 'nowrap'}}>{tok}</span>
                {i < b - a ? ' ' : ''}
              </React.Fragment>
            );
          })}
        </div>
      </div>
    </Layer>
  );
};

/* ---------- verification-only helpers ---------- */

/** Negative control: a saturated box 30px outside one edge of the safe area (or a faint white one: 'violateweak-left'). */
const Violate: React.FC = () => {
  const mode = React.useContext(DebugContext);
  const m = /^violate(weak)?-(left|right|top|bottom)$/.exec(mode);
  if (!m) return null;
  const box: Record<string, React.CSSProperties> = {left: {left: 40, top: 900}, right: {left: 925, top: 900}, top: {left: 500, top: 150}, bottom: {left: 500, top: 1450}};
  return <div style={{position: 'absolute', width: 40, height: 40, backgroundColor: m[1] ? WHITE : '#E5484D', ...box[m[2]]}} />;
};

/** Logs every text node's box, colour, size and effective opacity (console line starting AUDIT_JSON). */
const AuditProbe: React.FC = () => {
  const [handle] = useState(() => delayRender('audit'));
  useEffect(() => {
    const out: unknown[] = [];
    document.querySelectorAll('div,span').forEach((el) => {
      el.childNodes.forEach((n) => {
        if (n.nodeType !== 3 || !(n.textContent || '').trim()) return;
        const r = document.createRange();
        r.selectNodeContents(n);
        const b = r.getBoundingClientRect();
        const cs = getComputedStyle(el);
        let op = 1;
        for (let e: Element | null = el; e; e = e.parentElement) op *= parseFloat(getComputedStyle(e).opacity);
        out.push({text: (n.textContent || '').trim(), x0: b.left, y0: b.top, x1: b.right, y1: b.bottom, color: cs.color, size: parseFloat(cs.fontSize), weight: cs.fontWeight, opacity: op});
      });
    });
    console.log('AUDIT_JSON' + JSON.stringify(out));
    continueRender(handle);
  }, [handle]);
  return null;
};

